(()=>{
  const $=id=>document.getElementById(id);const G=window.GridDuel;let match=G.createMatch(),selectedBid=0,busy=false,soundOn=localStorage.getItem('grid-duel-sound')==='on',audioContext;
  const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
  function haptic(pattern){if(navigator.vibrate)navigator.vibrate(pattern)}
  function tone(kind){if(!soundOn)return;try{audioContext??=new AudioContext();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),tones={select:[480,.05],send:[320,.1],win:[660,.18],lose:[180,.22],draw:[390,.12]};const [frequency,duration]=tones[kind]||tones.select;oscillator.frequency.value=frequency;oscillator.type=kind==='lose'?'sawtooth':'sine';gain.gain.setValueAtTime(.055,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);oscillator.connect(gain).connect(audioContext.destination);oscillator.start();oscillator.stop(audioContext.currentTime+duration)}catch{}}
  function syncSound(){const button=$('soundButton');button.setAttribute('aria-pressed',String(soundOn));button.setAttribute('aria-label',soundOn?'Turn sound off':'Turn sound on');button.textContent=soundOn?'♬':'♩'}
  function renderPieces(){
    $('rivalPieces').innerHTML=Array.from({length:match.rivalEnergy},()=>'<i class="power-piece power-piece--rival">♟</i>').join('');
    $('playerPieces').innerHTML=Array.from({length:match.playerEnergy},(_,i)=>`<button class="power-piece ${i<selectedBid?'power-piece--selected':''}" type="button" data-piece="${i+1}" aria-label="Send ${i+1} power">♟</button>`).join('');
    $('playerPieces').querySelectorAll('[data-piece]').forEach(piece=>piece.addEventListener('click',()=>setBid(+piece.dataset.piece===selectedBid?0:+piece.dataset.piece)));
  }
  function renderTerritories(){
    $('territories').innerHTML=match.territories.map((owner,index)=>{const active=match.status==='playing'&&index===match.round;const label=owner==='player'?'YOURS':owner==='rival'?'RIVAL':owner==='draw'?'DRAW':active?'ACTIVE':'OPEN';const icon=owner==='player'||owner==='rival'?'◆':owner==='draw'?'—':active?'◎':'◇';return `<div class="territory ${active?'territory--active':''} ${owner?`territory--${owner}`:''}" data-territory="${index}"><strong>${icon}</strong><span>${label}</span></div>`}).join('');
  }
  function renderHistory(){const visible=match.history.length>0;$('historySection').hidden=!visible;if(!visible)return;$('historyList').innerHTML=[...match.history].reverse().map(item=>{const text=item.winner==='player'?'YOU WON':item.winner==='rival'?'RIVAL WON':'DRAW';return `<article class="history-row history-row--${item.winner}"><div class="history-label"><i>${item.winner==='draw'?'—':'◆'}</i><div><strong>Territory ${item.round}</strong><span>${text}</span></div></div><div class="history-bids"><b>${item.playerBid}</b> ♟ <i>vs</i> <b>${item.rivalBid}</b> ♟</div></article>`}).join('')}
  function render(){
    $('playerEnergy').textContent=match.playerEnergy;$('rivalEnergy').textContent=match.rivalEnergy;$('playerScore').textContent=match.playerScore;$('rivalScore').textContent=match.rivalScore;
    const tiebreakRound=match.round-G.TOTAL_TERRITORIES+1;$('roundLabel').textContent=match.status==='playing'?(match.tiebreak?`TIEBREAK ${tiebreakRound} / ${G.TIEBREAK_TERRITORIES}`:`ROUND ${match.round+1} / ${G.TOTAL_TERRITORIES}`):'MATCH OVER';$('activeTerritoryNumber').textContent=match.status==='playing'?(match.tiebreak?`TIEBREAK ${tiebreakRound}`:`TERRITORY ${match.round+1}`):'BATTLE COMPLETE';
    renderPieces();renderTerritories();renderHistory();updateSelection();
  }
  function updateSelection(){$('bidValue').textContent=`${selectedBid} selected`;$('lockButton').textContent=selectedBid?`SEND ${selectedBid} ${selectedBid===1?'PIECE':'PIECES'} ↑`:'SEND 0 · SAVE POWER'}
  function announce(title,text){$('announcementTitle').textContent=title;$('announcementText').textContent=text}
  function setBid(value){if(busy)return;selectedBid=Math.min(match.playerEnergy,Math.max(0,value));tone('select');haptic(8);renderPieces();updateSelection()}
  function clearMarch(){$('playerMarch').innerHTML='';$('rivalMarch').innerHTML='';$('battleResult').textContent='VS';$('battleResult').className=''}
  function marchTokens(id,count){$(id).innerHTML=Array.from({length:count},(_,i)=>`<i class="march-token" style="animation-delay:${i*.045}s">♟</i>`).join('')}
  function battleImpact(winner){const board=$('battleBoard'),flash=$('screenFlash');board.classList.remove('battle-board--player','battle-board--rival','battle-board--draw');void board.offsetWidth;board.classList.add(`battle-board--${winner}`);flash.className=`screen-flash screen-flash--${winner}`;for(let i=0;i<12;i++){const spark=document.createElement('i'),angle=Math.PI*2*i/12,distance=35+Math.random()*65;spark.className=`impact-spark impact-spark--${winner}`;spark.style.setProperty('--x',`${Math.cos(angle)*distance}px`);spark.style.setProperty('--y',`${Math.sin(angle)*distance}px`);$('marchZone').appendChild(spark);setTimeout(()=>spark.remove(),650)}setTimeout(()=>{board.classList.remove('battle-board--player','battle-board--rival','battle-board--draw');flash.className='screen-flash'},700)}
  function reset(){if($('outcomeDialog').open)$('outcomeDialog').close();match=G.createMatch();selectedBid=0;busy=false;$('arena').hidden=false;$('battleBoard').hidden=false;$('announcement').hidden=false;$('controlPanel').hidden=false;$('resultPanel').hidden=true;$('lockButton').disabled=false;clearMarch();announce('Choose your army','Tap a piece to select how many you will send.');render()}
  async function playRound(){
    if(busy||match.status!=='playing')return;busy=true;$('lockButton').disabled=true;const playerBid=selectedBid,rivalBid=G.chooseBotBid(match);tone('send');haptic(14);announce('Army sent','The rival is moving too…');marchTokens('playerMarch',playerBid);await wait(280);marchTokens('rivalMarch',rivalBid);await wait(600);
    match=G.resolveBattle(match,playerBid,rivalBid);const last=match.history.at(-1),startedTiebreak=match.tiebreak&&match.round===G.TOTAL_TERRITORIES;$('battleResult').className=`battle-result--${last.winner}`;
    if(last.winner==='player'){tone('win');haptic([15,40,25]);$('battleResult').textContent='YOU WIN';announce('Territory captured',`${playerBid} pieces beat ${rivalBid}.`)}else if(last.winner==='rival'){tone('lose');haptic([30,45,30]);$('battleResult').textContent='RIVAL WINS';announce('Rival captured it',`${rivalBid} pieces beat ${playerBid}.`)}else{tone('draw');haptic(20);$('battleResult').textContent='DRAW';announce('Deadlock',`Both armies sent ${playerBid}.`)}battleImpact(last.winner);
    selectedBid=0;render();const cell=document.querySelector(`[data-territory="${last.round-1}"]`);cell?.classList.add('territory--captured');await wait(900);
    if(match.status!=='playing'){finish();return}if(startedTiebreak){showOutcome('draw','TIEBREAK','3 MORE TERRITORIES',`The grid is tied ${match.playerScore} — ${match.rivalScore}.`);await wait(1550);if($('outcomeDialog').open)$('outcomeDialog').close()}clearMarch();announce(startedTiebreak?'Tiebreak begins':'Choose your next army',startedTiebreak?'Win the next 3 territories to break the tie.':'Tap a piece, then send it toward the grid.');busy=false;$('lockButton').disabled=false;render();
  }
  function showOutcome(type,kicker,title,summary){const dialog=$('outcomeDialog');dialog.dataset.outcome=type;$('outcomeKicker').textContent=kicker;$('outcomeTitle').textContent=title;$('outcomeScore').textContent=summary;$('outcomeIcon').textContent=type==='won'?'↑':type==='lost'?'↘':'=';if(!dialog.open)dialog.showModal()}
  function finish(){busy=false;$('arena').hidden=true;$('battleBoard').hidden=true;$('announcement').hidden=true;$('controlPanel').hidden=true;$('resultPanel').hidden=false;render();const details=`Final score: You ${match.playerScore} — ${match.rivalScore} Rival`;if(match.status==='won')showOutcome('won','VICTORY','YOU WIN',details);else if(match.status==='lost')showOutcome('lost','DEFEAT','YOU LOST',details);else showOutcome('draw','DRAW','GRID DEADLOCK',details)}
  $('lockButton').addEventListener('click',playRound);$('playAgainButton').addEventListener('click',reset);$('outcomeClose').addEventListener('click',()=>$('outcomeDialog').close());$('soundButton').addEventListener('click',()=>{soundOn=!soundOn;localStorage.setItem('grid-duel-sound',soundOn?'on':'off');syncSound();if(soundOn)tone('select')});$('restartButton').addEventListener('click',()=>{if(match.history.length&&match.status==='playing')$('restartDialog').showModal();else reset()});$('restartDialog').addEventListener('close',()=>{if($('restartDialog').returnValue==='confirm')reset()});syncSound();reset();
})();
